saveBranches: (u, p) => {
  need_(u, 'admin');
  const b = (p.branches || []).map(x => ({ id: String(x.id || uid_()), name: String(x.name || '').trim(), city: String(x.city || '').trim(), crNo: String(x.crNo || '').replace(/\s/g, ''), main: !!x.main })).filter(x => x.name);
  const map = { branches: JSON.stringify(b) };
  if (p.docTemplate) { const t = (p.docTemplate || []).map(x => ({ k: String(x.k || uid_()).slice(0, 20), name: String(x.name || '').trim(), issuer: String(x.issuer || '').trim() })).filter(x => x.name); map.docTemplate = JSON.stringify(t); }
  const crs = (() => { try { return JSON.parse(settings_().crList || '[]'); } catch (e) { return []; } })();
  b.forEach(x => { if (x.crNo && !crs.some(c => String(c.no) === x.crNo)) crs.push({ no: x.crNo, name: x.name }); });
  map.crList = JSON.stringify(crs);
  saveSettingsMap_(map);
  log_(u.username, 'تعديل الفروع', b.length + ' فرع');
  return true;
},
assignDocs: (u, p) => {
  need_(u, 'editor');
  const all = readAll_('Items'), out = [], ch = [];
  (p.list || []).forEach(x => { const ex = all.find(i => i.id === x.id); if (!ex) return; canSection_(u, ex.section);
    ['branch', 'docKey', 'crNo'].forEach(k => { if (x[k] !== undefined && String(ex[k] || '') !== String(x[k])) { ch.push({ at: now_(), itemId: ex.id, user: u.name || u.username, field: k, old: ex[k] || '', new: String(x[k]) }); ex[k] = String(x[k]); } });
    ex.updatedAt = now_(); ex.updatedBy = u.username; writeRow_('Items', ex._row, ex); out.push(cleanItem_(ex)); });
  if (ch.length) appendRows_('Changes', ch);
  log_(u.username, 'ربط مستندات بالفروع', out.length + ' مستند');
  return out;
},
